const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

const scenesMap = {};
for (const row of rows) {
  if (!scenesMap[row.scene_id]) {
    scenesMap[row.scene_id] = {
      scene_id: row.scene_id,
      scene_number: row.scene_number,
      title: row.scene_title,
      summary: row.summary,
      characters_present: JSON.parse(row.characters_present || '[]'),
      location: row.location,
      emotional_tone: row.emotional_tone,
      production_metadata: row.production_metadata || {},
      shots: []
    };
  }
  scenesMap[row.scene_id].shots.push({
    shot_id: row.shot_id,
    shot_number: row.shot_number,
    shot_type: row.shot_type,
    duration_seconds: row.duration_seconds,
    description: row.shot_description,
    camera_movement: row.camera_movement
  });
}

const fightScenes = Object.values(scenesMap);

return [{
  json: {
    project_id: projectId,
    title: rows[0].title,
    fight_scenes: fightScenes,
    total_fight_scenes: fightScenes.length
  }
}];

const responseText = $input.first().json.response || '{}';
let fightData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    fightData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      fightData = Object.entries(parsed).map(([key, val]) => ({ scene_id: key, ...val }));
    }
  }
} catch (e) {
  fightData = [];
}

const projectId = $('Execute Logic').item.json.project_id;
const fightScenes = $('Execute Logic').item.json.fight_scenes;

const shotUpdates = [];
let totalBeats = 0;

for (const fd of fightData) {
  if (!fd.beats) continue;
  const scene = fightScenes.find(s => s.scene_id === fd.scene_id);
  if (!scene) continue;

  for (const beat of fd.beats) {
    totalBeats++;
    shotUpdates.push({
      json: {
        shot_id: beat.shot_id,
        project_id: projectId,
        scene_id: fd.scene_id,
        fight_type: fd.fight_type || 'hand-to-hand',
        intensity: fd.intensity || 5,
        beat_number: beat.beat_number,
        action_description: beat.action,
        technique: beat.technique,
        characters_involved: JSON.stringify(beat.characters_involved || []),
        impact_level: beat.impact_level || 5,
        camera_angle: beat.camera_angle || 'eye-level',
        speed_ramp: beat.speed_ramp || 'none',
        sound_design: beat.sound_design || '',
        fight_metadata: JSON.stringify({
          fight_type: fd.fight_type,
          key_moments: fd.key_moments || [],
          safety_notes: fd.safety_notes || ''
        })
      }
    });
  }
}

return [{
  json: {
    project_id: projectId,
    shot_updates: shotUpdates,
    total_beats: totalBeats,
    total_fight_scenes: fightData.length
  }
}];

